    name: "Ganesh Chaturthi",
    slug: "ganesh-chaturthi",

    description:
      "Ganesh Chaturthi, also known in Maharashtra as Ganeshotsav or Ganapati Utsav, is a major festival dedicated to Lord Ganesha. In Maharashtra, particularly Mumbai and Pune, the festival has developed into a large public cultural celebration combining religious worship, community-organised mandals, temporary mandaps, idol installations, devotional music, aartis, cultural programmes, dhol-tasha performances, neighbourhood gatherings, food and immersion processions. For a visitor, Ganeshotsav is fundamentally different from a conventional temple-tour itinerary: the experience is distributed across public Ganpati mandals and neighbourhoods, and the practical planning problem is usually to select a geographically coherent set of darshan stops while accounting for queues, crowd density, transport restrictions, procession routes and immersion schedules. Mumbai is characterised by a very large city-wide network of public Ganpati mandals, while Pune has a particularly strong historical tradition around its five Manache Ganpati and the old-city peth areas.",

