    name: "Kali Puja / Diwali",
    slug: "kali-puja-diwali",

    description:
      "Kali Puja, also known as Shyama Puja in Bengal, is a major Hindu festival dedicated to Goddess Kali and is observed on the new moon night associated with the Diwali period. In West Bengal, Kali Puja and Diwali are closely intertwined, but the cultural emphasis is distinctive: worship of Kali, illuminated temples and community pujas, traditional household rituals, devotional music, neighbourhood celebrations, late-night worship, bhog and lighting are central elements. In Kolkata and surrounding parts of Bengal, the festival can be experienced through a combination of historic Kali temples, traditional household or bonedi pujas, community Kali installations, themed pandals, illuminated neighbourhoods and food or cultural stops. The practical itinerary problem is therefore different from Durga Puja: Kali Puja is primarily a night-oriented festival, and exact ritual timing, temple access, crowd conditions, lighting, traffic restrictions and late-night transport are particularly important. Outside Bengal, the broader Diwali festival family may instead centre on Lakshmi Puja, illuminated markets, diyas, religious ceremonies, cultural events, fairs and other regional traditions. The planner must therefore determine the user's regional festival mode before constructing an itinerary.",

