    description:
      "Jagaddhatri Puja in Chandannagar is one of Bengal's most distinctive large-scale community festivals, celebrated across Chandannagar and the closely connected festival areas of Mankundu and Bhadreswar. The celebration combines worship of Goddess Jagaddhatri with elaborate public pandals, traditionally styled and contemporary idols, enormous decorative lighting installations, community-organised pujas, cultural programmes and a major immersion procession. The festival is especially notable for its relationship with Chandannagar's urban and cultural history, its dense concentration of puja committees, the extensive alok-sajja lighting culture and the Dashami procession. Unlike a conventional temple pilgrimage, a Chandannagar Jagaddhatri itinerary is primarily a geographically organised pandal-and-lighting circuit, with walking used within dense areas and local transport used between separated clusters. The planner should treat Chandannagar, Mankundu and Bhadreswar as a connected regional festival zone while still respecting their individual geography and committee locations.",

