    description:
      "Jagaddhatri Puja in Rishra is a major Hooghly festival that follows a distinct local calendar from the better-known Chandannagar Jagaddhatri circuit. Rishra has developed its own dense network of barowari and community pujas, with themed and traditional idols, decorated pandals, extensive lighting, cultural activity and a substantial immersion procession. A defining characteristic of the Rishra festival is its later local occurrence: in recent documented years, Rishra's celebrations have begun around the period when Chandannagar's Jagaddhatri festival is approaching or completing its immersion. This creates an important regional planning opportunity: visitors who miss or finish the Chandannagar circuit can potentially experience Rishra afterward. Rishra should therefore be treated as its own festival destination and calendar occurrence rather than merely another neighbourhood of Chandannagar. Within Rishra, the itinerary should be built around local puja clusters, railway-side geography, major roads, lighting routes and current procession restrictions.",

